import sys
cubes = {i**3: i for i in range(1, 4000)}
found = []
for i in range(1, 4000):
   for j in range(i+1, 4000):
       s = i**3 + j**3
       if s in cubes:
           found.append((s, i, j))

sums = {}
for item in found:
   s, i, j = item
   if s not in sums:
       sums[s] = []
   sums[s].append((i, j))

for s in sorted(sums.keys()):
    if len(sums[s]) >= 2:
        print(f"Cube: {s} = {cubes[s]}^3, Ways: {sums[s]}")
        sys.exit(0)
